{"output": "{
  "title": "Electrical Circuits Fundamentals",
  "questions": [
    {
      "question": "What is the formula for Ohm's Law?",
      "options": [
        "V = I / R",
        "V = R / I",
        "V = IR",
        "I = VR"
      ],
      "correct_answer": "V = IR",
      "explanation": "Ohm's Law states that the voltage (V) across a resistor is directly proportional to the current (I) flowing through it and the resistance (R) of the resistor."
    },
    {
      "question": "How is the equivalent resistance calculated for resistors in series?",
      "options": [
        "1/R_eq = 1/R1 + 1/R2",
        "R_eq = R1 + R2",
        "R_eq = (R1 * R2) / (R1 + R2)",
        "R_eq = R1 - R2"
      ],
      "correct_answer": "R_eq = R1 + R2",
      "explanation": "For resistors connected in series, the equivalent resistance is the sum of the individual resistances."
    },
    {
      "question": "According to Kirchhoff's junction rule, what is the relationship between incoming and outgoing currents at a junction?",
      "options": [
        "Sum of I_in > Sum of I_out",
        "Sum of I_in < Sum of I_out",
        "Sum of I_in = Sum of I_out",
        "Sum of I_in = 0"
      ],
      "correct_answer": "Sum of I_in = Sum of I_out",
      "explanation": "Kirchhoff's junction rule, also known as the current law, states that the total current entering a junction must equal the total current leaving the junction."
    },
    {
      "question": "Which formula relates current (I) to drift velocity (v_d)?",
      "options": [
        "I = ne / Av_d",
        "I = neAv_d",
        "I = n / eAv_d",
        "I = e / nAv_d"
      ],
      "correct_answer": "I = neAv_d",
      "explanation": "The current (I) in a conductor is given by the product of the charge carrier density (n), the elementary charge (e), the cross-sectional area (A), and the drift velocity (v_d)."
    },
    {
      "question": "What does the Greek letter rho (Ï) represent in the context of electrical properties?",
      "options": [
        "Resistance",
        "Resistivity",
        "Conductivity",
        "Current"
      ],
      "correct_answer": "Resistivity",
      "explanation": "In electrical formulas, Ï (rho) typically represents resistivity, a material's intrinsic ability to oppose electric current."
    }
  ]
}"}

