{"flashcards_json": "[
  {
    "front": "Ohm's law?",
    "back": "V = IR for ohmic conductors."
  },
  {
    "front": "Series R_eq?",
    "back": "R_eq = R1 + R2"
  },
  {
    "front": "Parallel rule?",
    "back": "1/R_eq = 1/R1 + 1/R2"
  },
  {
    "front": "Kirchhoff junction?",
    "back": "Sum I_in = sum I_out"
  },
  {
    "front": "Drift velocity relation?",
    "back": "I = neAv_d"
  },
  {
    "front": "Resistivity formula?",
    "back": "ρ = RA/l"
  }
]"}

