    "front": "Direction cosines constraint?",
    "back": "l²+m²+n²=1"
  },
  {
    "front": "3D line form?",
    "back": "(x-x1)/a=(y-y1)/b=(z-z1)/c"
  },
  {
    "front": "Skew line distance?",
    "back": "Uses cross product."
  },
  {
    "front": "Direction ratios?",
    "back": "Define line direction."
  },
  {
    "front": "Angles with?",
    "back": "Coordinate axes."
  }
]"}

