              "Salivary amylase: initiates carbohydrate breakdown"
            ]
          },
          {
            "title": "B. Stomach",
            "details": [
              "HCl (hydrochloric acid): denatures proteins, activates enzymes",
              "Pepsin: protein digestion"
            ]
          },
          {
            "title": "C. Pancreas (Pancreatic Juice)",
            "details": [
              "Trypsin: protein digestion",
              "Lipase: fat digestion",
              "Amylase: carbohydrate digestion"
            ]
          },
          {
            "title": "D. Small Intestine",
            "details": [
              "Villi: site of nutrient absorption"
            ]
          }
        ]
      },
      {
        "title": "II. Photosynthesis and Energy Production",
        "concepts": [
          {
            "title": "A. Light-Dependent Reactions (Grana)",
            "details": [
