      "options": [
        "Oxidation",
        "Reduction",
        "Salt bridge only",
        "Insulator"
      ],
      "correct_answer": "Oxidation",
      "explanation": "Per electrochemistry excerpt."
    },
    {
      "question": "Standard E°cell:",
      "options": [
        "E°cathode-E°anode",
        "E°anode only",
        "Sum of ρ",
        "1/R_eq"
