    },
    {
      "question": "A line in 3D requires:",
      "options": [
        "Point and direction ratios",
        "Only one point",
        "Only slope",
        "Area"
      ],
      "correct_answer": "Point and direction ratios",
      "explanation": "Point-direction form."
